{
  "page_id": "airbytehq/airbyte/README.md",
  "source_sha256": "2f99c737827ef88aacb050440b239423bc1c7bb5a26843bc1245c7b15fe81f2a",
  "units": [
    {
      "ordinal": 0,
      "function": "promotion",
      "proposition": "Airbyte believes only open-source data movement can cover the long tail of sources while enabling connector customization.",
      "support": "Explicitly framed as a belief; connector-building options appear on line 44, but evidence for exclusivity is absent."
    },
    {
      "ordinal": 1,
      "function": "promotion",
      "proposition": "Airbyte's ultimate vision is movement from any source to any destination, including warehouses, lakes, and AI agents through Airbyte MCP.",
      "support": "Qualified as an ultimate vision; lines 38–44 describe connector and MCP capabilities without establishing universal coverage."
    },
    {
      "ordinal": 2,
      "function": "capability",
      "proposition": "Airbyte provides 700+ connectors for APIs, databases, data warehouses, data lakes, and AI applications.",
      "support": "Links the catalog at https://docs.airbyte.com/integrations/; line 46 also links a connector registry. No enumeration appears on the page."
    },
    {
      "ordinal": 3,
      "function": "evidence",
      "proposition": "The displayed screenshot was taken from Airbyte Cloud.",
      "support": "Adjacent Airbyte Connections UI image and Airbyte Cloud link at https://cloud.airbyte.com/signup."
    },
    {
      "ordinal": 4,
      "function": "transition",
      "proposition": "",
      "support": "Introduces the setup and usage bullets on lines 38–44."
    },
    {
      "ordinal": 5,
      "function": "instruction",
      "proposition": "Deploy Airbyte Core or sign up for Airbyte Cloud and follow its getting-started guide to move and sync data using 700+ connectors.",
      "support": "Links Core deployment instructions, Cloud signup, the Cloud getting-started guide, and https://docs.airbyte.com/integrations/."
    },
    {
      "ordinal": 6,
      "function": "capability",
      "proposition": "Through Airbyte MCP, agents including Claude, ChatGPT, Cursor, and VS Code Copilot can build and manage pipelines, troubleshoot syncs, read logs, and answer Airbyte questions; Cloud users should connect to the hosted server.",
      "support": "Links https://docs.airbyte.com/platform/airbyte-mcp; the following protected endpoint is `https://mcp.airbyte.com/mcp`. Line 44 names further MCP operations."
    },
    {
      "ordinal": 7,
      "function": "instruction",
      "proposition": "Sign in with OAuth for Cloud; Core's self-managed MCP setup runs locally against the deployment's API; consult the available tools.",
      "support": "Links the Cloud setup guide at https://docs.airbyte.com/platform/airbyte-mcp/install, self-managed setup at https://docs.airbyte.com/platform/airbyte-mcp/self-managed, and MCP tools at https://docs.airbyte.com/platform/airbyte-mcp/tools."
    },
    {
      "ordinal": 8,
      "function": "capability",
      "proposition": "In Airbyte Cloud only, the context layer lets AI agents read live data from supported sources, query supported destinations such as BigQuery and Snowflake without waiting for a sync, and search data; direct reads are read-only.",
      "support": "Links https://docs.airbyte.com/platform/context-layer; explicitly limited to Cloud, supported sources and destinations, and read-only direct reads."
    },
    {
      "ordinal": 9,
      "function": "instruction",
      "proposition": "Build connectors with the no-code Connector Builder or low-code CDK and orchestrate syncs with Airflow, Dagster, Kestra, or Airbyte API; through MCP, agents can publish and update custom connector manifests, run and cancel syncs, and change schedules.",
      "support": "Links Connector Builder and low-code CDK documentation, tutorials, Airflow/Dagster/Kestra integration guides, and https://reference.airbyte.com/; line 40 links MCP tools."
    },
    {
      "ordinal": 10,
      "function": "instruction",
      "proposition": "Try the demo app, consult the full documentation, and read recent announcements.",
      "support": "Links https://demo.airbyte.io/, https://docs.airbyte.com/, and https://airbyte.com/blog-categories/company-updates."
    },
    {
      "ordinal": 11,
      "function": "instruction",
      "proposition": "Consult the registry for a full list of connectors already available in Airbyte or Airbyte Cloud.",
      "support": "Links https://connectors.airbyte.com/files/generated_reports/connector_registry_report.html."
    },
    {
      "ordinal": 12,
      "function": "instruction",
      "proposition": "Join the Airbyte Community.",
      "support": "The following paragraph links Airbyte Community Slack and the Airbyte Forum."
    },
    {
      "ordinal": 13,
      "function": "capability",
      "proposition": "Airbyte Community Slack is a place to find the community, ask questions, and voice ideas.",
      "support": "Links https://join.slack.com/t/airbytehq/shared_invite/zt-497lmcwfo-rVj8NkG94vnVZV9H6wIkkg."
    },
    {
      "ordinal": 14,
      "function": "capability",
      "proposition": "Users can ask for help in the Airbyte Forum.",
      "support": "Links https://github.com/airbytehq/airbyte/discussions."
    },
    {
      "ordinal": 15,
      "function": "capability",
      "proposition": "Airbyte's roadmap is publicly viewable on GitHub.",
      "support": "Links https://github.com/orgs/airbytehq/projects/37/views/1?pane=issue&itemId=26937554."
    },
    {
      "ordinal": 16,
      "function": "instruction",
      "proposition": "Visit Airbyte's Content Hub and YouTube and subscribe to its newsletter for content about data engineering and building a data stack.",
      "support": "Links https://airbyte.com/content-hub, https://www.youtube.com/c/AirbyteHQ, and https://airbyte.com/newsletter."
    },
    {
      "ordinal": 17,
      "function": "transition",
      "proposition": "",
      "support": "Introduces contribution guidance on lines 56–64."
    },
    {
      "ordinal": 18,
      "function": "instruction",
      "proposition": "Open a GitHub issue if you find a problem with Airbyte.",
      "support": "Links https://github.com/airbytehq/airbyte/issues/new/choose; line 68 explicitly excludes security vulnerabilities from public issue reporting."
    },
    {
      "ordinal": 19,
      "function": "instruction",
      "proposition": "Consult the contributing guide to contribute to Airbyte and view its Code of Conduct.",
      "support": "Links https://docs.airbyte.com/contributing-to-airbyte/."
    },
    {
      "ordinal": 20,
      "function": "capability",
      "proposition": "Airbyte maintains a good-first-issues list containing bugs of relatively limited scope.",
      "support": "Links https://github.com/airbytehq/airbyte/labels/contributor-program; no individual issues are described on the page."
    },
    {
      "ordinal": 21,
      "function": "promotion",
      "proposition": "The good-first-issues list is a good starting point for gaining experience and learning the contribution process.",
      "support": "The preceding sentence describes those bugs as having relatively limited scope."
    },
    {
      "ordinal": 22,
      "function": "transition",
      "proposition": "",
      "support": "Introduces branch write-access and personal-fork requirements on lines 60–64."
    },
    {
      "ordinal": 23,
      "function": "instruction",
      "proposition": "When submitting a pull request, ensure Airbyte maintainers can write to your branch.",
      "support": "Line 62 specifies the \"Allow edits from maintainers\" checkbox and personal-account fork requirement."
    },
    {
      "ordinal": 24,
      "function": "capability",
      "proposition": "Maintainer write access enables direct formatting fixes and dependency updates and significantly speeds review and approval.",
      "support": "The preceding sentence specifies branch write access; evidence measuring the claimed speed improvement is absent."
    },
    {
      "ordinal": 25,
      "function": "instruction",
      "proposition": "Check \"Allow edits from maintainers\" when submitting a PR to enable Airbyte maintainers' write access.",
      "support": "The following sentence requires a personal-account fork; line 62 links GitHub's documentation on allowing changes to fork-based PR branches."
    },
    {
      "ordinal": 26,
      "function": "instruction",
      "proposition": "Create the PR from a fork in a personal GitHub account rather than an organization account, or the maintainer-edit option will not appear.",
      "support": "The following sentence attributes this condition to GitHub's organization-fork security restrictions; line 62 links the relevant GitHub documentation."
    },
    {
      "ordinal": 27,
      "function": "qualification",
      "proposition": "The personal-fork requirement follows from GitHub's additional security restrictions for PRs from organization forks.",
      "support": "Line 62 links https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/working-with-forks/allowing-changes-to-a-pull-request-branch-created-from-a-fork."
    },
    {
      "ordinal": 28,
      "function": "instruction",
      "proposition": "Consult GitHub's documentation about PRs from forks for more information about its security model.",
      "support": "Links https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/working-with-forks/allowing-changes-to-a-pull-request-branch-created-from-a-fork."
    },
    {
      "ordinal": 29,
      "function": "instruction",
      "proposition": "Consult the contribution workflow documentation for further contribution requirements.",
      "support": "Links https://docs.airbyte.com/platform/contributing-to-airbyte#standard-contribution-workflow."
    },
    {
      "ordinal": 30,
      "function": "transition",
      "proposition": "",
      "support": "Introduces vulnerability reporting instructions and Enterprise security features."
    },
    {
      "ordinal": 31,
      "function": "promotion",
      "proposition": "Airbyte treats security issues very seriously.",
      "support": "The following sentences specify a vulnerability disclosure and reporting process; no operational evidence of seriousness is provided."
    },
    {
      "ordinal": 32,
      "function": "instruction",
      "proposition": "Do not report security vulnerabilities through GitHub issues or the public forum.",
      "support": "The following sentence directs vulnerability reports to the affected product's disclosure policy at https://airbyte.com/security/vdp."
    },
    {
      "ordinal": 33,
      "function": "instruction",
      "proposition": "If you believe you found a vulnerability, read the affected product's disclosure policy and report it using the security reporting page.",
      "support": "Links https://airbyte.com/security/vdp; the preceding sentence prohibits GitHub issues and public forum posts for vulnerabilities."
    },
    {
      "ordinal": 34,
      "function": "capability",
      "proposition": "Airbyte Enterprise offers additional security features, among other additions, beyond Airbyte open-source.",
      "support": "Links https://airbyte.com/airbyte-enterprise; specific additional features are absent from the page."
    },
    {
      "ordinal": 35,
      "function": "transition",
      "proposition": "",
      "support": "Introduces licensing references on line 74."
    },
    {
      "ordinal": 36,
      "function": "instruction",
      "proposition": "Consult LICENSE for licensing information and the licensing FAQ for questions.",
      "support": "Links docs/LICENSE and https://docs.airbyte.com/platform/developer-guides/licenses/license-faq."
    },
    {
      "ordinal": 37,
      "function": "transition",
      "proposition": "",
      "support": "Introduces the acknowledgment and thank-you-page reference."
    },
    {
      "ordinal": 38,
      "function": "other",
      "proposition": "Airbyte would not be possible without support and assistance from other open-source tools and companies.",
      "support": "The following sentence links THANK-YOU.md; specific supporting tools, companies, and contributions are absent from the eligible prose."
    },
    {
      "ordinal": 39,
      "function": "instruction",
      "proposition": "Visit the thank-you page to learn more about how Airbyte is built.",
      "support": "Links THANK-YOU.md."
    }
  ]
}
